package com.harvestflow.api.dto.delivery; import com.harvestflow.api.domain.entity.MarketOrder; import java.time.Instant;
public record ReceiptResponse(String orderId,String farmer,String buyer,String produce,double quantity,double finalAmount,Instant deliveryDateTime,String paymentStatus,String paymentMethod,String transactionReference){ public static ReceiptResponse from(MarketOrder o,String ref){return new ReceiptResponse(o.getId().toString(),o.getSeller().getName(),o.getBuyer().getName(),o.getCropName(),o.getQuantity(),o.getTotalAmount(),o.getDeliveredAt(),o.getPaymentStatus()==null?null:o.getPaymentStatus().name(),o.getPaymentMethod()==null?null:o.getPaymentMethod().name(),ref);} }
